320	const TOP_HELP = `${USAGE_PREFIX} <サブコマンド> [--help]
321	
322	サブコマンド:
323	${Object.entries(COMMANDS)
324	  .map(([name, c]) => `  ${name.padEnd(14)} ${c.summary}`)
325	  .join("\n")}
326	
327	サブコマンドごとの引数・出力・終了コードは、<サブコマンド> --help で示す。
328	`;
329	
330	/** 位置で決まる引数の先頭から、サブコマンドの名前を探す。名前の語の数が多いものを優先する */
331	function findCommand(positionals: readonly string[]): { name: string; command: Command; rest: string[] } | undefined {
332	  for (let n = Math.min(2, positionals.length); n >= 1; n--) {
333	    const name = positionals.slice(0, n).join(" ");
334	    const command = COMMANDS[name];
335	    if (command !== undefined) return { name, command, rest: positionals.slice(n) };
336	  }
337	  return undefined;
338	}
