340	async function main(argv: readonly string[]): Promise<number> {
341	  let help: boolean;
342	  let positionals: string[];
343	  let pptxSkill: string | undefined;
344	  let recreateAll: boolean;
345	  try {
346	    const parsed = parseArgs({
347	      args: [...argv],
348	      options: {
349	        help: { type: "boolean", short: "h" },
350	        "pptx-skill": { type: "string" },
351	        "recreate-all": { type: "boolean" },
352	      },
353	      allowPositionals: true,
354	      strict: true,
355	    });
356	    help = parsed.values.help ?? false;
357	    positionals = parsed.positionals;
358	    pptxSkill = parsed.values["pptx-skill"];
359	    recreateAll = parsed.values["recreate-all"] ?? false;
360	  } catch (e) {
361	    process.stderr.write(`${e instanceof Error ? e.message : String(e)}\n\n${TOP_HELP}`);
362	    return 2;
363	  }
364	  const found = findCommand(positionals);
365	  if (found === undefined) {
366	    const name = positionals.join(" ");
367	    if (help && (name === "" || name === "setup")) {
368	      process.stdout.write(TOP_HELP);
369	      return 0;
370	    }
371	    process.stderr.write(`${name === "" ? "サブコマンドを指定する" : `存在しないサブコマンド: ${name}`}\n\n${TOP_HELP}`);
372	    return 2;
373	  }
374	  const { command } = found;
375	  if (help) {
376	    process.stdout.write(command.help);
377	    return 0;
378	  }
379	  try {
380	    return await command.run({ positionals: found.rest, pptxSkill, recreateAll });
381	  } catch (e) {
382	    if (e instanceof UsageError) {
383	      process.stderr.write(`${e.message}\n\n${command.help}`);
384	      return 2;
385	    }
386	    // 想定していない誤りも、終了コード 1 (検査の指摘あり) と区別できるよう、実行の誤り 2 にする
387	    const known = e instanceof SetupError || e instanceof ExecutionError;
388	    process.stderr.write(`${known ? e.message : e instanceof Error ? (e.stack ?? e.message) : String(e)}\n`);
389	    return 2;
390	  }
391	}
